-- workspace.sqlite as v0.4.2 (tag v0.4.2) writes it, for LibrarySchemaUpgradeTests.
-- Generated by running v0.4.2's own code: a fresh library plus a native chat whose
-- run recorded its native harness session, an activity, a folder and a note, and
-- then OpenClaw dashboard-era rows (a dashboard chat, a hidden platform chat, a
-- gateway trace, agent, session and import, a web surface profile and a profile)
-- written with v0.4.2's triggers, so its paired-sync bookkeeping is v0.4.2's.
-- Two conversations of execution owners were added afterwards by hand, as
-- v0.4.2's journal projection writes them: a Linux host's and an iPhone's, each
-- with its rows and its whole transcript in execution_conversations.transcript,
-- and two recorded versions (one message, one transcript document).
-- Tables and their rows come first, then indexes and triggers. The peer-sync
-- capture triggers (paired_<table>_INSERT/UPDATE/DELETE, about 1.5 MB of SQL
-- generated from each shared table's columns) are left out; the upgrade drops
-- every trigger before it renames anything, these included.

CREATE TABLE bot_conversation_entries(
  id TEXT PRIMARY KEY, conversation TEXT NOT NULL, entry_id INTEGER NOT NULL,
  role TEXT NOT NULL, text TEXT NOT NULL, error TEXT, stopped INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE TABLE bot_conversations(
  id TEXT PRIMARY KEY, machine_id TEXT NOT NULL, bot_id TEXT NOT NULL, bot_name TEXT NOT NULL,
  conversation_id INTEGER NOT NULL, kind TEXT NOT NULL, parent_conversation_id INTEGER, forked_at INTEGER,
  title TEXT, pinned INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, deleted_at TEXT);
CREATE TABLE calendar_execution_conflicts(event_id TEXT PRIMARY KEY);
CREATE TABLE calendar_published_runs(id TEXT PRIMARY KEY, event_id TEXT NOT NULL, device_id TEXT NOT NULL, payload_json TEXT NOT NULL);
CREATE TABLE calendar_replica_context(singleton INTEGER PRIMARY KEY CHECK(singleton=1), library_id TEXT NOT NULL, workspace_id TEXT NOT NULL);
CREATE TABLE calendar_run_publishers(event_id TEXT NOT NULL, device_id TEXT NOT NULL, PRIMARY KEY(event_id,device_id));
CREATE TABLE calendar_task_executors(event_id TEXT PRIMARY KEY, device_id TEXT NOT NULL, tools_json TEXT);
CREATE TABLE dashboard_agents (
  id TEXT PRIMARY KEY, user_id TEXT NOT NULL DEFAULT '', codename TEXT NOT NULL DEFAULT '',
  display_name TEXT NOT NULL DEFAULT '', role TEXT, description TEXT,
  icon TEXT NOT NULL DEFAULT 'bot', execution_location TEXT NOT NULL DEFAULT 'local',
  agent_bucket TEXT NOT NULL DEFAULT 'local_cli',
  governing_plane TEXT NOT NULL DEFAULT 'wovenmatter_macos',
  authority_kind TEXT NOT NULL DEFAULT 'device_owned', authority_device_id TEXT,
  authority_agent_id TEXT,
  runtime_kind TEXT NOT NULL DEFAULT 'openclaw', runtime_device_id TEXT,
  platform_codename TEXT, model TEXT, fallback_model TEXT,
  status TEXT NOT NULL DEFAULT 'offline', is_primary INTEGER NOT NULL DEFAULT 0,
  runtime_metadata_json TEXT NOT NULL DEFAULT '{}', revision INTEGER NOT NULL DEFAULT 1,
  origin_device_id TEXT, deleted_at TEXT, created_at TEXT NOT NULL DEFAULT '',
  updated_at TEXT NOT NULL DEFAULT '', desktop_owned INTEGER NOT NULL DEFAULT 0
);
