INSERT INTO "workspace_history_schema" VALUES(2);
CREATE TABLE workspace_input_contexts(
  id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL REFERENCES dashboard_conversations(id),
  note_id TEXT, created_at TEXT NOT NULL);
CREATE TABLE workspace_mcp_bot_machines(machine_id TEXT PRIMARY KEY, active INTEGER NOT NULL);
CREATE TABLE workspace_mcp_callers(id TEXT PRIMARY KEY, display_name TEXT, machine_id TEXT, revoked INTEGER NOT NULL DEFAULT 0);
