CREATE TRIGGER activity_index_event_delete AFTER DELETE ON dashboard_run_events BEGIN
  UPDATE desktop_activity_revision SET revision=revision+1 WHERE singleton=1;
  UPDATE desktop_activity_index SET deleted=1,summary=NULL,
    revision=(SELECT revision FROM desktop_activity_revision WHERE singleton=1)
    WHERE id=''||old.id;
END;
CREATE TRIGGER activity_index_event_insert AFTER INSERT ON dashboard_run_events  BEGIN
  UPDATE desktop_activity_revision SET revision=revision+1 WHERE singleton=1;
  INSERT INTO desktop_activity_index(id,source_kind,source_id,conversation_id,run_id,revision,deleted)
    VALUES(''||new.id,'event',new.id,new.conversation_id,new.run_id,
      (SELECT revision FROM desktop_activity_revision WHERE singleton=1),CASE WHEN 0 THEN 1 ELSE 0 END)
  ON CONFLICT(id) DO UPDATE SET conversation_id=excluded.conversation_id,run_id=excluded.run_id,
    revision=excluded.revision,deleted=excluded.deleted,summary=NULL,activity_id=NULL;
END;
CREATE TRIGGER activity_index_event_update AFTER UPDATE ON dashboard_run_events WHEN old.content IS NOT new.content OR old.event_type IS NOT new.event_type OR old.run_id IS NOT new.run_id OR old.conversation_id IS NOT new.conversation_id OR old.created_at IS NOT new.created_at BEGIN
  UPDATE desktop_activity_revision SET revision=revision+1 WHERE singleton=1;
  INSERT INTO desktop_activity_index(id,source_kind,source_id,conversation_id,run_id,revision,deleted)
    VALUES(''||new.id,'event',new.id,new.conversation_id,new.run_id,
      (SELECT revision FROM desktop_activity_revision WHERE singleton=1),CASE WHEN 0 THEN 1 ELSE 0 END)
  ON CONFLICT(id) DO UPDATE SET conversation_id=excluded.conversation_id,run_id=excluded.run_id,
    revision=excluded.revision,deleted=excluded.deleted,summary=NULL,activity_id=NULL;
END;
CREATE TRIGGER activity_index_trace_delete AFTER DELETE ON dashboard_run_trace_events BEGIN
  UPDATE desktop_activity_revision SET revision=revision+1 WHERE singleton=1;
  UPDATE desktop_activity_index SET deleted=1,summary=NULL,
    revision=(SELECT revision FROM desktop_activity_revision WHERE singleton=1)
    WHERE id='trace-'||old.id;
END;
CREATE TRIGGER activity_index_trace_insert AFTER INSERT ON dashboard_run_trace_events  BEGIN
  UPDATE desktop_activity_revision SET revision=revision+1 WHERE singleton=1;
  INSERT INTO desktop_activity_index(id,source_kind,source_id,conversation_id,run_id,revision,deleted)
    VALUES('trace-'||new.id,'trace',new.id,new.conversation_id,new.run_id,
      (SELECT revision FROM desktop_activity_revision WHERE singleton=1),CASE WHEN new.is_visible=0 OR new.event_type IN ('assistant_delta','assistant_replace','done') THEN 1 ELSE 0 END)
  ON CONFLICT(id) DO UPDATE SET conversation_id=excluded.conversation_id,run_id=excluded.run_id,
    revision=excluded.revision,deleted=excluded.deleted,summary=NULL,activity_id=NULL;
END;
CREATE TRIGGER activity_index_trace_update AFTER UPDATE ON dashboard_run_trace_events WHEN old.raw_event_json IS NOT new.raw_event_json OR old.content IS NOT new.content OR old.is_visible IS NOT new.is_visible OR old.event_type IS NOT new.event_type OR old.event_name IS NOT new.event_name OR old.event_phase IS NOT new.event_phase OR old.tool_name IS NOT new.tool_name OR old.run_id IS NOT new.run_id OR old.conversation_id IS NOT new.conversation_id OR old.created_at IS NOT new.created_at OR old.seq IS NOT new.seq BEGIN
  UPDATE desktop_activity_revision SET revision=revision+1 WHERE singleton=1;
  INSERT INTO desktop_activity_index(id,source_kind,source_id,conversation_id,run_id,revision,deleted)
    VALUES('trace-'||new.id,'trace',new.id,new.conversation_id,new.run_id,
      (SELECT revision FROM desktop_activity_revision WHERE singleton=1),CASE WHEN new.is_visible=0 OR new.event_type IN ('assistant_delta','assistant_replace','done') THEN 1 ELSE 0 END)
  ON CONFLICT(id) DO UPDATE SET conversation_id=excluded.conversation_id,run_id=excluded.run_id,
    revision=excluded.revision,deleted=excluded.deleted,summary=NULL,activity_id=NULL;
END;
CREATE TRIGGER conversation_message_delete
AFTER DELETE ON dashboard_messages BEGIN
  UPDATE desktop_activity_revision SET revision=revision+1 WHERE singleton=1;
  INSERT INTO desktop_message_revisions(id,revision)
    VALUES(old.id,(SELECT revision FROM desktop_activity_revision WHERE singleton=1))
    ON CONFLICT(id) DO UPDATE SET revision=excluded.revision;
END;
