CREATE TRIGGER execution_stream_dashboard_conversations_delete AFTER DELETE ON dashboard_conversations
WHEN NOT EXISTS (SELECT 1 FROM execution_conversations f WHERE f.id = OLD.id AND f.deleted = 0) AND NOT EXISTS (SELECT 1 FROM paired_conversation_owners o WHERE o.id = OLD.id AND o.device_id <> COALESCE((SELECT host_device_id FROM library_identity WHERE singleton = 1), '')) AND NOT EXISTS (SELECT 1 FROM desktop_openclaw_gateway_sessions g WHERE g.conversation_id = OLD.id) AND EXISTS (SELECT 1 FROM desktop_local_acp_sessions s WHERE s.conversation_id = OLD.id AND s.remote_workspace_id IS NULL)
BEGIN
  INSERT INTO execution_stream_changes(conversation_id, entity_kind, entity_id)
