CREATE TRIGGER library_agent_metadata AFTER UPDATE OF display_name ON dashboard_agents
WHEN NEW.display_name != OLD.display_name
BEGIN UPDATE library_settings SET value=CAST(value AS INTEGER)+1 WHERE key='revision'; END;
CREATE TRIGGER library_changed_message AFTER UPDATE OF content,status ON dashboard_messages
 WHEN (SELECT applying FROM paired_library_clock)=0 AND (NEW.content != OLD.content OR NEW.status != OLD.status) BEGIN UPDATE library_messages SET dirty=1 WHERE message_id=NEW.id; END;
CREATE TRIGGER library_cleared_conversation AFTER UPDATE OF context_generation ON dashboard_conversations
 WHEN (SELECT applying FROM paired_library_clock)=0 AND (NEW.context_generation > OLD.context_generation) BEGIN DELETE FROM library_messages WHERE message_id IN (SELECT id FROM dashboard_messages WHERE conversation_id=NEW.id); END;
CREATE TRIGGER library_conversation_metadata AFTER UPDATE OF title,agent_id,agent_codename,user_id,desktop_owned,governing_plane ON dashboard_conversations
WHEN EXISTS(SELECT 1 FROM library_items WHERE conversation_id=NEW.id)
BEGIN UPDATE library_settings SET value=CAST(value AS INTEGER)+1 WHERE key='revision'; END;
CREATE TRIGGER library_deleted_conversation AFTER DELETE ON dashboard_conversations
BEGIN
  DELETE FROM library_messages WHERE message_id IN (SELECT message_id FROM library_items WHERE conversation_id=OLD.id)
    OR message_id IN (SELECT id FROM dashboard_messages WHERE conversation_id=OLD.id);
  DELETE FROM library_locations WHERE conversation_id=OLD.id;
END;
CREATE TRIGGER library_deleted_message AFTER DELETE ON dashboard_messages
BEGIN DELETE FROM library_messages WHERE message_id=OLD.id; END;
CREATE TRIGGER library_delivery_revision_DELETE AFTER DELETE ON workspace_session_deliveries
WHEN EXISTS(SELECT 1 FROM library_items WHERE message_id=OLD.message_id)
BEGIN UPDATE library_settings SET value=CAST(value AS INTEGER)+1 WHERE key='revision'; END;
