 WHEN (SELECT applying FROM paired_library_clock)=0 BEGIN UPDATE library_messages SET dirty=1 WHERE message_id=NEW.message_id; END;
CREATE TRIGGER library_new_message AFTER INSERT ON dashboard_messages
 WHEN (SELECT applying FROM paired_library_clock)=0 AND (NEW.role IN ('user','assistant') AND julianday(NEW.created_at) >=
  (SELECT julianday(value) FROM library_settings WHERE key='activated_at')) BEGIN INSERT OR IGNORE INTO library_messages(message_id) VALUES(NEW.id); END;
CREATE TRIGGER library_revision_DELETE AFTER DELETE ON library_items
BEGIN UPDATE library_settings SET value=CAST(value AS INTEGER)+1 WHERE key='revision'; END;
CREATE TRIGGER library_revision_INSERT AFTER INSERT ON library_items
BEGIN UPDATE library_settings SET value=CAST(value AS INTEGER)+1 WHERE key='revision'; END;
CREATE TRIGGER library_revision_UPDATE AFTER UPDATE ON library_items
BEGIN UPDATE library_settings SET value=CAST(value AS INTEGER)+1 WHERE key='revision'; END;
CREATE TRIGGER library_session_revision_DELETE AFTER DELETE ON desktop_local_acp_sessions
WHEN EXISTS(SELECT 1 FROM library_items WHERE conversation_id=OLD.conversation_id)
BEGIN UPDATE library_settings SET value=CAST(value AS INTEGER)+1 WHERE key='revision'; END;
CREATE TRIGGER library_session_revision_INSERT AFTER INSERT ON desktop_local_acp_sessions
WHEN EXISTS(SELECT 1 FROM library_items WHERE conversation_id=NEW.conversation_id)
BEGIN UPDATE library_settings SET value=CAST(value AS INTEGER)+1 WHERE key='revision'; END;
CREATE TRIGGER library_session_revision_UPDATE AFTER UPDATE OF runtime_kind,remote_workspace_id ON desktop_local_acp_sessions
WHEN EXISTS(SELECT 1 FROM library_items WHERE conversation_id=NEW.conversation_id)
BEGIN UPDATE library_settings SET value=CAST(value AS INTEGER)+1 WHERE key='revision'; END;
CREATE TRIGGER library_trashed_conversation AFTER UPDATE OF deleted_at ON dashboard_conversations
WHEN NEW.deleted_at IS NOT OLD.deleted_at
BEGIN
  UPDATE library_settings SET value=CAST(value AS INTEGER)+1 WHERE key='revision';
END;
CREATE TRIGGER paired_agent_owner AFTER INSERT ON dashboard_agents
WHEN (SELECT applying FROM paired_library_clock WHERE singleton=1)=0 BEGIN
  INSERT OR IGNORE INTO paired_agent_owners VALUES(NEW.id,(SELECT device_id FROM paired_library_clock WHERE singleton=1));
END;
CREATE TRIGGER paired_calendar_owner AFTER INSERT ON dashboard_calendar_items
WHEN (SELECT applying FROM paired_library_clock WHERE singleton=1)=0 BEGIN
  INSERT OR IGNORE INTO paired_calendar_owners VALUES(NEW.id,(SELECT device_id FROM paired_library_clock WHERE singleton=1));
END;
CREATE TRIGGER paired_conversation_owner AFTER INSERT ON dashboard_conversations
WHEN (SELECT applying FROM paired_library_clock WHERE singleton=1)=0
  AND NOT EXISTS(SELECT 1 FROM execution_conversations c WHERE c.id=NEW.id) BEGIN
  INSERT OR IGNORE INTO paired_conversation_owners VALUES(NEW.id,(SELECT device_id FROM paired_library_clock WHERE singleton=1));
END;
CREATE TRIGGER workspace_calendar_runs_revision_delete
AFTER DELETE ON workspace_calendar_runs BEGIN
  UPDATE desktop_dashboard_revision SET revision=revision+1 WHERE singleton=1;
END;
CREATE TRIGGER workspace_calendar_runs_revision_insert
AFTER INSERT ON workspace_calendar_runs BEGIN
  UPDATE desktop_dashboard_revision SET revision=revision+1 WHERE singleton=1;
END;
CREATE TRIGGER workspace_calendar_runs_revision_update
AFTER UPDATE ON workspace_calendar_runs BEGIN
  UPDATE desktop_dashboard_revision SET revision=revision+1 WHERE singleton=1;
END;
CREATE TRIGGER workspace_goal_cleanup BEFORE DELETE ON workspace_session_goals BEGIN
  DELETE FROM workspace_goal_runs WHERE goal_id=json_extract(old.value,'$.id');
  DELETE FROM workspace_goal_usage WHERE goal_id=json_extract(old.value,'$.id');
END;
CREATE TRIGGER workspace_mcp_caller_insert AFTER INSERT ON dashboard_conversations BEGIN
  INSERT OR IGNORE INTO workspace_mcp_callers(id) VALUES(new.id);
END;
CREATE TRIGGER workspace_session_grants_source_id_bot_insert BEFORE INSERT ON workspace_session_grants
WHEN NEW.source_id LIKE 'woven:bot:%'
BEGIN INSERT INTO workspace_mcp_callers(id) SELECT NEW.source_id WHERE NOT EXISTS (SELECT 1 FROM workspace_mcp_callers WHERE id=NEW.source_id); END;
CREATE TRIGGER workspace_session_grants_source_id_bot_update BEFORE UPDATE OF source_id ON workspace_session_grants
WHEN NEW.source_id LIKE 'woven:bot:%'
BEGIN INSERT INTO workspace_mcp_callers(id) SELECT NEW.source_id WHERE NOT EXISTS (SELECT 1 FROM workspace_mcp_callers WHERE id=NEW.source_id); END;
CREATE TRIGGER workspace_session_relationships_coordinator_id_bot_insert BEFORE INSERT ON workspace_session_relationships
WHEN NEW.coordinator_id LIKE 'woven:bot:%'
BEGIN INSERT INTO workspace_mcp_callers(id) SELECT NEW.coordinator_id WHERE NOT EXISTS (SELECT 1 FROM workspace_mcp_callers WHERE id=NEW.coordinator_id); END;
CREATE TRIGGER workspace_session_relationships_coordinator_id_bot_update BEFORE UPDATE OF coordinator_id ON workspace_session_relationships
WHEN NEW.coordinator_id LIKE 'woven:bot:%'
BEGIN INSERT INTO workspace_mcp_callers(id) SELECT NEW.coordinator_id WHERE NOT EXISTS (SELECT 1 FROM workspace_mcp_callers WHERE id=NEW.coordinator_id); END;
CREATE TRIGGER workspace_session_relationships_created_by_bot_insert BEFORE INSERT ON workspace_session_relationships
WHEN NEW.created_by LIKE 'woven:bot:%'
BEGIN INSERT INTO workspace_mcp_callers(id) SELECT NEW.created_by WHERE NOT EXISTS (SELECT 1 FROM workspace_mcp_callers WHERE id=NEW.created_by); END;
CREATE TRIGGER workspace_session_relationships_created_by_bot_update BEFORE UPDATE OF created_by ON workspace_session_relationships
WHEN NEW.created_by LIKE 'woven:bot:%'
BEGIN INSERT INTO workspace_mcp_callers(id) SELECT NEW.created_by WHERE NOT EXISTS (SELECT 1 FROM workspace_mcp_callers WHERE id=NEW.created_by); END;
CREATE TRIGGER workspace_session_tool_defaults AFTER INSERT ON dashboard_conversations BEGIN
  INSERT OR IGNORE INTO workspace_session_tools(session_id,enabled_json,defaults_applied)
    VALUES(new.id,(SELECT json_extract(value,'$.enabledByDefault') FROM workspace_tool_settings WHERE id=1),0);
  INSERT OR IGNORE INTO workspace_executor_sessions(session_id,profiles_json)
    VALUES(new.id,COALESCE((SELECT json_extract(value,'$.executor.defaultProfiles') FROM workspace_tool_settings WHERE id=1),'[]'));
END;
